import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`youtube-ads`,heroTitle:`Launch YouTube ad campaigns in minutes`,heroSubtitle:`Perplexity Computer reviews your channel, studies the market, and builds YouTube ads with scripts, thumbnails, and targeting logic.`,inputUrlCta:`Build my YouTube ads`,inputUrlPlaceholder:`youtube.com/@yourchannel`,inputUrlPrefill:`Go to {url} and build a YouTube advertising plan for this brand. (1) Analyze the top-performing channel or video content for hooks, pacing, positioning, and offer framing. (2) Research competitor YouTube ad strategies and identify the audience segments they appear to target. (3) Recommend campaign structure, creative angles, targeting segments, and funnel stages for YouTube ads. (4) Write five complete YouTube ad scripts with matching thumbnail concepts and opening hooks. (5) Deliver a launch-ready campaign plan with ad variations, targeting notes, and production guidance.`,heroOverlaySteps:[`Reviewing your strongest videos for hooks, pacing, and offer framing`,`Studying competitor YouTube ads and the audiences they appear to target`,`Designing campaigns around the formats most likely to convert for your offer`,`Five ad scripts, thumbnail concepts, and campaign structure ready to launch`],generatingSteps:[`Visiting {url} to analyze the current channel, videos, and creative patterns`,`Designing an agent to benchmark competitor YouTube ad strategies and audience targets`,`Configuring script writing, creative angle selection, and campaign structure recommendations`,`Packaging the work into launch-ready scripts, thumbnails, and targeting guidance`],featureSectionTitle:`From channel content to a real ads system`,featureCardTitles:[`Connects to your video marketing workflow`,`Outputs your team can produce`],featureCardDescriptions:[`Computer breaks the job into creative analysis, competitor research, audience planning, and ad writing so the final campaign is grounded in what already works.`,`Docs, Sheets, briefs, and planning tools can stay connected so the channel review and ad production plan live in one workflow.`,`Creative angles. Audience segments. Thumbnail concepts. Five scripts. Campaign structure. Computer gives your team a launch package instead of a loose brainstorm.`],capabilitySectionTitle:`Your YouTube ads strategist, on demand`,capabilitySectionSubtitle:`Paste your channel or video, step away, and come back to a campaign your team can build from.`,capabilityCards:[{title:`Creative Analysis`,description:`Computer can review your best-performing content to identify the hooks, pacing, and offer framing worth carrying into paid creative.`},{title:`Competitor Ad Research`,description:`Computer can benchmark the ad angles, formats, and targeting clues competitors rely on so your team can respond with sharper positioning.`},{title:`Script Writing`,description:`Computer can write complete YouTube ad scripts with openings, narrative flow, CTA language, and thumbnail direction.`},{title:`Connect Your Tools`,description:`Computer can package scripts, planning notes, and targeting guidance across Docs, Sheets, and production workflows.`},{title:`Audience Planning`,description:`Computer can map likely audience segments and funnel stages so the creative and campaign structure match the viewers you want to reach.`},{title:`Refresh Campaign Ideas`,description:`Computer can revisit your channel and market later to suggest new ad angles as content performance and competition evolve.`}]});export{t as default};
